const KEY='shici-memory-v1', DAY=86400000, GAPS=[1,1,4,23], DECKS=['IELTS','TOEFL','GRE','PTE'];
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const RELEASES_URL=`${globalThis.APP_META.repositoryUrl}/releases`, LATEST_RELEASE_API=`https://api.github.com/repos/${globalThis.APP_META.githubOwner}/${globalThis.APP_META.githubRepo}/releases/latest`;
const defaults={dailyGoal:10,decks:[...DECKS],excludeBasic:false,revealMode:false,pendingPlan:null,queueCollapsed:false,hasSeenGuide:false,records:{},streak:0,lastCheckin:null,checkins:[],history:{},skippedSessions:[],session:null,virtualOffset:0,lastDateAction:null};
