function recoverLegacyHistory(data){data.checkins.forEach(date=>{if(data.history[date])return;let items=[],recoveredFrom='records';if(data.session?.checkedIn&&(data.session.checkinDate||data.session.date)===date&&Array.isArray(data.session.items)){items=data.session.items.map(item=>{const attempts=Array.isArray(item.attempts)?item.attempts.map(attempt=>({...attempt})):[],initialRating=attempts.find(attempt=>attempt.phase==='initial')?.rating||item.rating||null,reinforcementAttempts=attempts.filter(attempt=>attempt.phase==='reinforcement'),hadDifficulty=attempts.some(attempt=>['hard','again'].includes(attempt.rating))||['hard','again'].includes(item.rating);return {w:item.w,type:item.type||'new',rating:item.rating||null,initialRating,finalRating:item.rating||null,hadDifficulty,attempts,reinforcementAttempts,previousLast:null,daysSincePrevious:null}});recoveredFrom='session'}else{items=Object.entries(data.records||{}).filter(([,r])=>r.last===date).map(([w,r])=>({w,type:(r.stage??0)===0?'new':'review',rating:null,previousLast:null,daysSincePrevious:null}))}data.history[date]={date,taskDate:data.session?.date||date,plan:data.session?.plan||{dailyGoal:data.dailyGoal,decks:[...data.decks],excludeBasic:!!data.excludeBasic},items,reconstructed:true,recoveredFrom}})}
function backfillHistoryRounds(data){const seen={};Object.keys(data.history).sort().forEach(date=>{(data.history[date].items||[]).forEach(item=>{if(Number.isInteger(item.learningRound)){seen[item.w]=Math.max(seen[item.w]||0,item.learningRound);return}if(item.type==='new'){item.learningRound=1;seen[item.w]=Math.max(seen[item.w]||0,1);item.roundInferred=true}else if(seen[item.w]){item.learningRound=seen[item.w]+1;seen[item.w]=item.learningRound;item.roundInferred=true}else{item.learningRound=null;item.roundInferred=true}})})}
function load(){try{const raw=JSON.parse(localStorage.getItem(KEY)||'{}');const data={...defaults,...raw};if(data.pendingPlan){data.dailyGoal=data.pendingPlan.dailyGoal;data.decks=[...data.pendingPlan.decks];data.excludeBasic=!!data.pendingPlan.excludeBasic;data.pendingPlan=null}data.checkins=Array.isArray(data.checkins)?data.checkins:[];data.history=data.history&&typeof data.history==='object'?data.history:{};data.skippedSessions=Array.isArray(data.skippedSessions)?data.skippedSessions:[];data.virtualOffset=Number(data.virtualOffset)||0;Object.values(data.records||{}).forEach(r=>{if(!r.dueDay&&r.due){const d=new Date(r.due);r.dueDay=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}});recoverLegacyHistory(data);backfillHistoryRounds(data);return data}catch{return {...defaults,records:{},checkins:[],history:{},skippedSessions:[]}}}
function save(){localStorage.setItem(KEY,JSON.stringify(state));syncPush()}
const sync={enabled:false,ready:false,rev:null,busy:false,pending:false};let adopting=false;let adoptStreak=0;const MAX_AUTO_ADOPTS=3;const SYNC_NOTICE_COOLDOWN_MS=30000;const BOOTSTRAP_RETRY_MS=15000;let lastSyncNoticeAt=0;let bootstrapTimer=null;let bootstrapNotified=false;
async function api(path,options){try{const res=await fetch(path,Object.assign({cache:'no-store'},options||{}));if(res.status===404)return {status:404,body:null};let body=null;try{body=await res.json()}catch{return {status:res.status,ok:res.ok,body:null}}return {status:res.status,ok:res.ok,body}}catch(error){return {status:0,error:error}}}
function syncStatusText(){if(!sync.enabled)return 'offline';if(sync.conflict)return 'conflict';if(sync.ready)return 'cloud';return 'connecting'}
async function syncPush(){if(!(typeof fetch==='function')||!sync.enabled||!sync.ready){sync.pending=false;return}if(sync.busy){sync.pending=true;return}sync.busy=true;try{for(;;){const result=await api('/api/state',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({baseRev:sync.rev,state})});if(result.status===200&&result.body){adoptStreak=0;sync.conflict=false;sync.rev=result.body.rev}else if(result.status===409){if(adoptStreak>=MAX_AUTO_ADOPTS){sync.conflict=true;sync.ready=false;toast('云端数据与本机连续冲突，已停止自动同步以避免互相覆盖；请刷新页面或检查其他设备');scheduleBootstrapRetry();break}const adopted=await syncAdopt();if(!adopted)break}else{if(result.status===0)syncNotice('无法连接云端同步服务，数据暂存本机');else syncNotice('云端同步保存失败（HTTP '+result.status+'），数据暂存本机')}if(!sync.pending)break;sync.pending=false}}finally{sync.busy=false}}
async function syncPushNow(force){if(!(typeof fetch==='function')||!sync.enabled){sync.pending=false;return}if(sync.busy){sync.pending=true;return}const baseRev=force?null:sync.rev;const result=await api('/api/state',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({baseRev,state})});if(result.status===200&&result.body){adoptStreak=0;sync.conflict=false;sync.ready=true;sync.rev=result.body.rev;if(force)toast('已覆盖云端共享数据，其他设备下次同步将使用本机的版本')}else if(result.status===409&&!force){await syncAdopt()}else if(result.status!==0&&result.status!==409){syncNotice('云端同步不可用，数据暂存本机')}}
function syncNotice(message){const now=Date.now();if(now-lastSyncNoticeAt>=SYNC_NOTICE_COOLDOWN_MS){lastSyncNoticeAt=now;toast(message)}}
async function syncAdopt(){if(adopting)return false;adopting=true;try{const result=await api('/api/state');if(result.status!==200||!result.body)return false;adoptStreak+=1;localStorage.setItem(KEY,JSON.stringify(result.body.state));state=load();queue=[];current=0;libraryPage=1;calendarCursor=effectiveDate();historyCalendarCursor=effectiveDate();selectedHistoryDate=null;sync.rev=result.body.rev;sync.ready=true;if(adoptStreak===1)toast('已采用云端最新数据，本机未同步的改动被云端版本覆盖');refreshAll();return true}finally{adopting=false}}
async function syncSeed(){const result=await api('/api/state',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({baseRev:0,state})});if(result.status===200&&result.body){adoptStreak=0;sync.conflict=false;sync.ready=true;sync.rev=result.body.rev;return true}if(result.status===409)return syncAdopt();return false}
function scheduleBootstrapRetry(){if(bootstrapTimer!=null||typeof fetch!=='function')return;bootstrapTimer=setTimeout(()=>{bootstrapTimer=null;if(typeof fetch==='function'&&!sync.ready)syncBootstrap()},BOOTSTRAP_RETRY_MS);if(bootstrapTimer&&typeof bootstrapTimer.unref==='function')bootstrapTimer.unref()}
async function syncBootstrap(){if(typeof fetch!=='function')return;let health=null;try{health=await fetch('/api/health',{cache:'no-store'})}catch{health=null}if(!(health&&health.ok)){sync.enabled=false;if(!bootstrapNotified){bootstrapNotified=true;toast('无法连接同步服务，学习数据暂存本机')}scheduleBootstrapRetry();return}sync.enabled=true;const result=await api('/api/state');if(result.status===200&&result.body){localStorage.setItem(KEY,JSON.stringify(result.body.state));state=load();queue=[];current=0;libraryPage=1;calendarCursor=effectiveDate();historyCalendarCursor=effectiveDate();selectedHistoryDate=null;sync.rev=result.body.rev;sync.ready=true;sync.conflict=false;sync.pending=false;adoptStreak=0;bootstrapNotified=false;if(bootstrapTimer!=null){clearTimeout(bootstrapTimer);bootstrapTimer=null}refreshAll()}else if(result.status===404){const ok=await syncSeed();if(!ok)bootstrapFail('云端数据读取失败，将自动重试')}else bootstrapFail('无法连接云端同步服务，将自动重试')}
