function refreshAll(){$('#dailyGoal').value=state.dailyGoal;$$('[name=deck]').forEach(x=>x.checked=state.decks.includes(x.value));$('#excludeBasic').checked=!!state.excludeBasic;$('#revealMode').checked=!!state.revealMode;syncTodaySessionToPlan();save();hydrateQueue();renderCalendar();renderHistory();renderPendingPlan();if(!state.hasSeenGuide)showView('guide')}
function startOfDay(d){return new Date(d.getFullYear(),d.getMonth(),d.getDate())}
function effectiveDate(){return new Date(startOfDay(new Date()).getTime()+state.virtualOffset*DAY)}
function dateKey(d=effectiveDate()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function dateFromKey(key){const [y,m,d]=key.split('-').map(Number);return new Date(y,m-1,d)}
function dayNumber(d=effectiveDate()){return Math.round(startOfDay(d).getTime()/DAY)}
const VOCAB_BY_WORD=new Map(VOCAB.map(word=>[word.w.toLocaleLowerCase(),word]));
const DEFINITION_STOPWORDS=new Set('the a an and or of to in on for with without by from as is are be being been that this something someone into not no one having have has very more most make become cause used using whose which when where after before'.split(' '));
const PREFIXES=[['un','否定、不'],['re','再次、返回'],['dis','否定、分离'],['pre','在前、预先'],['post','在后'],['inter','在……之间'],['trans','跨越、转变'],['sub','在下、次级'],['anti','反对、抵抗'],['over','过度、在上'],['under','不足、在下'],['non','非、不']];
