function definitionKeywordWords(word){const tokens=[...new Set((word.en.toLowerCase().match(/[a-z]{3,}/g)||[]).filter(t=>!DEFINITION_STOPWORDS.has(t)))];return tokens.map(token=>VOCAB_BY_WORD.get(token)).filter(Boolean).filter(item=>item.w!==word.w).slice(0,8)}
function affixNotes(word){const lower=word.w.toLowerCase(),notes=[];const prefix=PREFIXES.find(([part])=>lower.startsWith(part)&&lower.length>part.length+3);const suffix=SUFFIXES.find(([part])=>lower.endsWith(part)&&lower.length>part.length+3);if(prefix)notes.push(`${prefix[0]}-：${prefix[1]}`);if(suffix)notes.push(`-${suffix[0]}：${suffix[1]}`);return notes}
function relationWords(word){if(word.syn.length)return word.syn.map(name=>VOCAB_BY_WORD.get(name.toLowerCase())||{w:name,p:'',zh:''});return definitionKeywordWords(word)}
function escapeHtml(value=''){return String(value).replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]))}
function parseVersion(value){const match=String(value||'').trim().match(/^v?(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?(?:\+[0-9A-Za-z.-]+)?$/);if(!match)return null;return {parts:match.slice(1,4).map(Number),prerelease:match[4]?match[4].split('.'):[]}}
function compareVersions(left,right){const a=parseVersion(left),b=parseVersion(right);if(!a||!b)return null;for(let i=0;i<3;i++){if(a.parts[i]!==b.parts[i])return a.parts[i]>b.parts[i]?1:-1}if(!a.prerelease.length&&!b.prerelease.length)return 0;if(!a.prerelease.length)return 1;if(!b.prerelease.length)return -1;const length=Math.max(a.prerelease.length,b.prerelease.length);for(let i=0;i<length;i++){const x=a.prerelease[i],y=b.prerelease[i];if(x===undefined)return -1;if(y===undefined)return 1;if(x===y)continue;const xNumber=/^\d+$/.test(x),yNumber=/^\d+$/.test(y);if(xNumber&&yNumber)return Number(x)>Number(y)?1:-1;if(xNumber!==yNumber)return xNumber?-1:1;return x>y?1:-1}return 0}
