function renderProjectMeta(){const meta=globalThis.APP_META;$('#currentVersion').textContent=`v${meta.version}`;$('#authorLink').textContent=meta.author;$('#authorLink').href=`https://github.com/${meta.githubOwner}`;$('#repositoryLink').href=meta.repositoryUrl;$('#pagesLink').href=meta.pagesUrl;$('#allReleasesLink').href=RELEASES_URL;$('#latestReleaseLink').href=`${RELEASES_URL}/latest`}
function setUpdateState(name,message,{showLatest=false,downloadUrl='',showReload=false}={}){const project=$('#projectUpdate'),button=$('#checkUpdateBtn'),latest=$('#latestReleaseLink'),download=$('#downloadUpdateLink'),reload=$('#reloadForUpdateBtn');project.dataset.state=name;$('#updateStatus').textContent=message;latest.classList.toggle('hidden',!showLatest);download.classList.toggle('hidden',!downloadUrl);if(downloadUrl)download.href=downloadUrl;reload.classList.toggle('hidden',!showReload);button.textContent=name==='loading'?'检查中…':name==='idle'?'检查更新':'再次检查'}
function releaseZipAsset(release){return (release?.assets||[]).find(asset=>typeof asset?.name==='string'&&/\.zip$/i.test(asset.name)&&typeof asset.browser_download_url==='string')||null}
function isPagesDeployment(){return (globalThis.location?.hostname||'').toLowerCase().endsWith('.github.io')}
function releaseRequestError(message,details={}){const error=new Error(message);Object.assign(error,details);return error}
async function fetchLatestRelease(fetcher=globalThis.fetch,{timeoutMs=9000}={}){if(typeof fetcher!=='function')throw releaseRequestError('Fetch unavailable',{code:'network'});const controller=typeof AbortController==='function'?new AbortController():null,timer=controller&&timeoutMs>0?setTimeout(()=>controller.abort(),timeoutMs):null;let response;try{response=await fetcher(LATEST_RELEASE_API,{headers:{Accept:'application/vnd.github+json','X-GitHub-Api-Version':'2022-11-28'},cache:'no-store',signal:controller?.signal})}catch(error){if(error?.name==='AbortError')throw releaseRequestError('Request timed out',{code:'timeout'});throw releaseRequestError('Network request failed',{code:'network',cause:error})}finally{if(timer)clearTimeout(timer)}if(!response?.ok)throw releaseRequestError(`GitHub returned ${response?.status||0}`,{status:response?.status||0});const release=await response.json();if(!release||typeof release.tag_name!=='string')throw releaseRequestError('Invalid release response',{code:'invalid'});return release}
function checkForUpdates(fetcher=globalThis.fetch,options={}){if(updateCheckPromise)return updateCheckPromise;const online=options.online??(typeof navigator==='undefined'||navigator.onLine!==false);if(!online){setUpdateState('error','当前处于离线状态；联网后再试，或直接打开全部历史版本。');return Promise.resolve({status:'offline'})}const button=$('#checkUpdateBtn');button.disabled=true;setUpdateState('loading','正在连接 GitHub Releases…');updateCheckPromise=(async()=>{try{const release=await fetchLatestRelease(fetcher,options),remote=versionLabel(release.tag_name),comparison=compareVersions(release.tag_name,globalThis.APP_META.version);if(comparison===null){setUpdateState('error','GitHub 最新版本标签格式无法识别，请直接查看历史版本。');return {status:'invalid',release}}if(comparison>0){const zip=releaseZipAsset(release);if(isPagesDeployment()){setUpdateState('available',`发现新版本 ${remote}：在线版由 GitHub Pages 自动更新，点击“立即刷新”即可使用最新版，学习记录不受影响。`,{showLatest:true,showReload:true});return {status:'available',release,channel:'pages'}}if(zip){setUpdateState('available',`发现新版本 ${remote}，可一键下载更新包；解压后覆盖旧文件即可，学习记录保存在浏览器中，不会丢失。`,{showLatest:true,downloadUrl:zip.browser_download_url});return {status:'available',release,downloadUrl:zip.browser_download_url}}setUpdateState('available',`发现新版本 ${remote}，可前往 GitHub 查看说明并下载。`,{showLatest:true});return {status:'available',release}}if(comparison===0){setUpdateState('current',`当前已是最新版 ${remote}。`);return {status:'current',release}}setUpdateState('current',`当前为开发版本 v${globalThis.APP_META.version}，公开最新版是 ${remote}。`);return {status:'development',release}}catch(error){if(error.status===404){setUpdateState('error','GitHub 中还没有公开 Release，请稍后再试或查看仓库。');return {status:'missing'}}if(error.status===403||error.status===429){setUpdateState('error','GitHub 暂时限制了更新查询，请稍后再试或直接查看历史版本。');return {status:'limited'}}if(error.code==='timeout'){setUpdateState('error','检查更新超时，请稍后再试或直接查看历史版本。');return {status:'timeout'}}setUpdateState('error','暂时无法连接 GitHub，请检查网络或直接查看历史版本。');return {status:'error'}}finally{button.disabled=false;updateCheckPromise=null}})();return updateCheckPromise}
function frequencyText(word){const parts=[];if(word.collins)parts.push(`Collins ${word.collins} 星`);if(word.oxford)parts.push('Oxford 3000');if(word.bnc)parts.push(`BNC 词频 #${word.bnc}`);if(word.frq)parts.push(`现代语料 #${word.frq}`);return parts.join(' · ')||'暂无词频等级记录'}
