function isBasicWord(word){const tags=word.tags||[];return tags.includes('zk')||tags.includes('gk')}
function selectedWords(plan=state){return VOCAB.filter(w=>w.src.some(s=>plan.decks.includes(s))&&(!plan.excludeBasic||!isBasicWord(w)))}
function snapshotHadDifficulty(item){return item.hadDifficulty??((item.attempts||[]).some(attempt=>['hard','again'].includes(attempt.rating))||['hard','again'].includes(item.initialRating||item.rating))}
