function difficultySummary(){const map=new Map;Object.keys(state.history).sort().forEach(date=>{(state.history[date].items||[]).forEach(item=>{if(!snapshotHadDifficulty(item))return;const current=map.get(item.w)||{w:item.w,count:0,events:[],lastDate:null};current.count++;current.lastDate=date;current.events.push({date,round:item.learningRound||null,inferred:!!item.roundInferred,initialRating:initialAttemptRating(item),reinforcementAttempts:reinforcementAttemptCount(item)});map.set(item.w,current)})});return map}
